"""One-command local browser workstation."""
from __future__ import annotations
import argparse, json, threading, webbrowser
from datetime import date
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Sequence
from .data import fetch_daily_bars, fetch_sec_facts
from .model import run
from .paper import advance

HTML='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>finance-quant</title><style>body{font:14px system-ui;background:#0d1117;color:#e6edf3;margin:0}.w{max-width:1300px;margin:auto;padding:24px}.g{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.c,.p{background:#161b22;border:1px solid #30363d;border-radius:10px;padding:14px;margin:10px 0}.v{font-size:22px}.m{color:#8b949e}.good{color:#3fb950}.bad{color:#f85149}svg{width:100%;height:360px;background:#0d1117}table{width:100%;border-collapse:collapse}td,th{padding:7px;border-bottom:1px solid #30363d;text-align:right}td:first-child,th:first-child{text-align:left}.scroll{max-height:420px;overflow:auto}@media(max-width:800px){.g{grid-template-columns:1fr 1fr}}</style><div class=w><h1 id=t>finance-quant</h1><div class=m id=sub></div><div class=g id=cards></div><div class=p><svg id=chart viewBox="0 0 1200 360" preserveAspectRatio="none"></svg></div><div class=g style="grid-template-columns:1fr 1fr"><div class=p><h3>Persistent local paper</h3><div id=paper></div></div><div class=p><h3>Latest PIT SEC KG facts</h3><div class=scroll><table><tbody id=facts></tbody></table></div></div></div><div class=p><h3>Walk-forward predictions</h3><div class=scroll><table><thead><tr><th>Decision</th><th>Outcome</th><th>Price</th><th>Price+KG</th><th>Actual</th><th>Right?</th></tr></thead><tbody id=pred></tbody></table></div></div><div class="p m" id=src></div></div><script>const pct=x=>(x*100).toFixed(2)+'%',num=x=>Number(x).toLocaleString(undefined,{maximumFractionDigits:2});function C(l,v,d){let e=document.createElement('div');e.className='c';e.innerHTML=`<div class=m>${l}</div><div class="v ${d==null?'':d>=0?'good':'bad'}">${v}</div>`;return e}function draw(r){let b=r.bars.slice(-500),p=new Map(r.predictions.kg.map(x=>[x.decision_day,x])),s=document.querySelector('#chart'),ys=b.map(x=>x.close),lo=Math.min(...ys),hi=Math.max(...ys),W=1200,H=360,x=i=>20+i*(W-40)/Math.max(1,b.length-1),y=v=>H-20-(v-lo)*(H-40)/Math.max(1e-9,hi-lo),d='';b.forEach((q,i)=>d+=(i?'L':'M')+x(i)+','+y(q.close)+' ');s.innerHTML=`<path d="${d}" fill="none" stroke="#58a6ff" stroke-width="2" vector-effect="non-scaling-stroke"/>`;b.forEach((q,i)=>{let z=p.get(q.day);if(z)s.insertAdjacentHTML('beforeend',`<circle cx="${x(i)}" cy="${y(q.close)}" r="3" fill="${z.predicted>0?'#3fb950':'#f85149'}"/>`)})}async function main(){let s=await(await fetch('/api/state')).json(),r=s.research,b=r.metrics.baseline,k=r.metrics.kg,d=r.metrics.delta;document.querySelector('#t').textContent=r.ticker+' predictive workstation';document.querySelector('#sub').textContent=r.start+' → '+r.end+' · objective: next-session open→close return';let c=document.querySelector('#cards');[['Price direction',pct(b.directional_accuracy)],['KG direction',pct(k.directional_accuracy),d.directional_accuracy],['Price long/cash',pct(b.long_cash_return)],['KG long/cash',pct(k.long_cash_return),d.long_cash_return],['Price corr',b.correlation.toFixed(3)],['KG corr',k.correlation.toFixed(3),d.correlation],['Live price',pct(r.live_signal.baseline_predicted)],['Live KG',pct(r.live_signal.kg_predicted),r.live_signal.kg_predicted-r.live_signal.baseline_predicted]].forEach(x=>c.append(C(...x)));draw(r);let p=s.paper;document.querySelector('#paper').innerHTML=p?`<div class=v>$${num(p.nav)} NAV</div><div>$${num(p.cash)} cash · ${p.position_quantity} shares</div><div class=m>${p.pending_signal?(p.pending_signal.predicted>0?'pending LONG ':'pending CASH ')+pct(p.pending_signal.predicted):''}</div>`:'disabled';document.querySelector('#facts').innerHTML=r.latest_kg_facts.map(f=>`<tr><td>${f.concept}</td><td>${f.period_end}</td><td>${f.filed}</td><td>${num(f.value)}</td></tr>`).join('');let bm=new Map(r.predictions.baseline.map(x=>[x.decision_day,x]));document.querySelector('#pred').innerHTML=r.predictions.kg.slice(-150).reverse().map(x=>{let q=bm.get(x.decision_day),ok=(x.predicted>=0)===(x.actual>=0);return `<tr><td>${x.decision_day}</td><td>${x.outcome_day}</td><td>${pct(q.predicted)}</td><td>${pct(x.predicted)}</td><td>${pct(x.actual)}</td><td class=${ok?'good':'bad'}>${ok?'YES':'NO'}</td></tr>`}).join('');document.querySelector('#src').textContent='Sources: '+r.sources.price+'; '+r.sources.kg}main()</script>'''

class Handler(BaseHTTPRequestHandler):
    state: dict[str,Any]={}
    def do_GET(self):
        raw=(json.dumps(type(self).state,separators=(',',':')) if self.path=='/api/state' else HTML if self.path in {'/','/index.html'} else None)
        if raw is None: self.send_error(404); return
        data=raw.encode(); self.send_response(200); self.send_header('Content-Type','application/json' if self.path=='/api/state' else 'text/html; charset=utf-8'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data)
    def log_message(self,*_): pass

def parser() -> argparse.ArgumentParser:
    p=argparse.ArgumentParser(prog='finance-quant workstation'); p.add_argument('--ticker',default='AAPL'); p.add_argument('--start',default='2018-01-01'); p.add_argument('--end',default=date.today().isoformat()); p.add_argument('--capital',type=float,default=100000); p.add_argument('--state-dir',default='.finance-quant/workstation'); p.add_argument('--port',type=int,default=8765); p.add_argument('--min-train',type=int,default=126); p.add_argument('--train-window',type=int,default=756); p.add_argument('--retrain-every',type=int,default=21); p.add_argument('--no-paper',action='store_true'); p.add_argument('--no-browser',action='store_true'); p.add_argument('--json',action='store_true'); return p

def main(argv: Sequence[str]|None=None) -> int:
    a=parser().parse_args(argv); bars=fetch_daily_bars(a.ticker,a.start,a.end); facts=fetch_sec_facts(a.ticker); research=run(a.ticker,bars,facts,min_train=a.min_train,train_window=a.train_window,retrain_every=a.retrain_every); state={'research':research,'paper':None if a.no_paper else advance(research,state_dir=a.state_dir,initial_cash=a.capital)}
    if a.json: print(json.dumps(state,indent=2)); return 0
    Handler.state=state; server=ThreadingHTTPServer(('127.0.0.1',a.port),Handler); url=f'http://127.0.0.1:{a.port}/'; print(url)
    if not a.no_browser: threading.Timer(.3,lambda:webbrowser.open(url)).start()
    try: server.serve_forever()
    except KeyboardInterrupt: pass
    finally: server.server_close()
    return 0
